insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m1-test-r1','b1-m1-test',11,'multiple_choice','reading','{"prompt":"Why did the writer wake up late?","options":["The alarm was off","The phone battery had died","They went to bed very late"],"answer":1,"passage":{"title":"The day I missed my flight","text":"I had been planning the trip for months, so I was really excited. On the morning of the flight, I woke up late because my phone had died during the night. I jumped into a taxi, but there was an accident on the highway and we were stuck for forty minutes. By the time I got to the airport, the gate had already closed. I was furious with myself. Luckily, the woman at the information desk was incredibly kind: she found me a seat on an evening flight for a small fee. While I was waiting, I met another traveler who had missed the same flight, and we ended up having dinner together. Looking back, it was one of the best days of the trip."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
