insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m3-test-r1','b1-m3-test',11,'multiple_choice','reading','{"prompt":"What is one argument FOR the ban?","options":["Students concentrate better","Parents can contact children","Phones help to record lessons"],"answer":0,"passage":{"title":"Should phones be banned in schools?","text":"Several countries have banned cell phones in classrooms, and the debate is growing. Supporters say that students concentrate better and talk to each other more during breaks. Some teachers also report fewer cases of online bullying during the school day. On the other hand, many parents want to be able to contact their children, especially in an emergency. Some students argue that phones can be useful learning tools, for example to look up information or record lessons. In my opinion, a total ban is too extreme. I think schools should keep phones away during lessons but allow them in specific activities, when the teacher decides they are useful."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m3-test-r2','b1-m3-test',12,'multiple_choice','reading','{"prompt":"Why do many parents disagree with a ban?","options":["Phones are expensive","They want to contact their children in emergencies","Teachers use phones too"],"answer":1,"passage":{"title":"Should phones be banned in schools?","text":"Several countries have banned cell phones in classrooms, and the debate is growing. Supporters say that students concentrate better and talk to each other more during breaks. Some teachers also report fewer cases of online bullying during the school day. On the other hand, many parents want to be able to contact their children, especially in an emergency. Some students argue that phones can be useful learning tools, for example to look up information or record lessons. In my opinion, a total ban is too extreme. I think schools should keep phones away during lessons but allow them in specific activities, when the teacher decides they are useful."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
