insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m4-test-r1','b1-m4-test',11,'multiple_choice','reading','{"prompt":"What is the problem?","options":["A truck has broken down","Two drivers will be on vacation","Customers canceled orders"],"answer":1,"passage":{"title":"An email to a manager","text":"Dear Ms. Taylor,\nI''m writing about the delivery schedule for next week. Unfortunately, two of our drivers will be on vacation from Monday to Wednesday, so we won''t be able to deliver all the orders on time. I''d like to suggest two options: we could hire a temporary driver for three days, or we could ask some customers if they would accept their deliveries on Thursday. I''ve already checked, and the temporary driver would cost around $450. Could you let me know which option you prefer by Friday? I''m happy to discuss it in a call if that''s easier.\nBest regards,\nRafael"}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m4-test-r2','b1-m4-test',12,'multiple_choice','reading','{"prompt":"Which is one of Rafael''s suggestions?","options":["Hire a temporary driver","Cancel all the orders","Deliver everything on Monday"],"answer":0,"passage":{"title":"An email to a manager","text":"Dear Ms. Taylor,\nI''m writing about the delivery schedule for next week. Unfortunately, two of our drivers will be on vacation from Monday to Wednesday, so we won''t be able to deliver all the orders on time. I''d like to suggest two options: we could hire a temporary driver for three days, or we could ask some customers if they would accept their deliveries on Thursday. I''ve already checked, and the temporary driver would cost around $450. Could you let me know which option you prefer by Friday? I''m happy to discuss it in a call if that''s easier.\nBest regards,\nRafael"}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m4-test-r3','b1-m4-test',13,'multiple_choice','reading','{"prompt":"What does Rafael ask Ms. Taylor to do?","options":["Call the customers","Choose an option by Friday","Pay the driver"],"answer":1,"passage":{"title":"An email to a manager","text":"Dear Ms. Taylor,\nI''m writing about the delivery schedule for next week. Unfortunately, two of our drivers will be on vacation from Monday to Wednesday, so we won''t be able to deliver all the orders on time. I''d like to suggest two options: we could hire a temporary driver for three days, or we could ask some customers if they would accept their deliveries on Thursday. I''ve already checked, and the temporary driver would cost around $450. Could you let me know which option you prefer by Friday? I''m happy to discuss it in a call if that''s easier.\nBest regards,\nRafael"}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m5-test-r1','b1-m5-test',11,'multiple_choice','reading','{"prompt":"Why did the writer start volunteering?","options":["To find a job","Because they didn''t know anyone","Because the university required it"],"answer":1,"passage":{"title":"Volunteering","text":"When I moved to Boston, I didn''t know anyone, so I decided to volunteer at a food bank on Saturday mornings. At first I was nervous because my English wasn''t very good, but the other volunteers were patient and helped me with new words. We sort donations, pack boxes and give them to families who need them. After six months, I''ve made real friends, my English has improved a lot and I understand the city much better. I''ve also realized how many people struggle to pay for basic things, even in a rich country. I''d recommend volunteering to anyone who has just moved abroad."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
