insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m7-test-r1','b1-m7-test',11,'multiple_choice','reading','{"prompt":"What is the movie about?","options":["Three friends'' last vacation together","A fishing competition","A university professor"],"answer":0,"passage":{"title":"A movie review","text":"I didn''t expect much from \"The Last Summer\", but it turned out to be one of the best movies I''ve seen this year. It tells the story of three friends who spend their final vacation together before going to different universities. The acting is natural, and the dialogue feels like real conversations between young people. The photography of the small fishing village is beautiful. My only criticism is that the second half is a bit slow, and one of the characters isn''t developed enough. Even so, I''d definitely recommend it, especially if you enjoy quiet, emotional stories rather than action."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m7-test-r2','b1-m7-test',12,'multiple_choice','reading','{"prompt":"What did the reviewer criticize?","options":["The acting","The photography","The slow second half"],"answer":2,"passage":{"title":"A movie review","text":"I didn''t expect much from \"The Last Summer\", but it turned out to be one of the best movies I''ve seen this year. It tells the story of three friends who spend their final vacation together before going to different universities. The acting is natural, and the dialogue feels like real conversations between young people. The photography of the small fishing village is beautiful. My only criticism is that the second half is a bit slow, and one of the characters isn''t developed enough. Even so, I''d definitely recommend it, especially if you enjoy quiet, emotional stories rather than action."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
