insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m8-test-r1','b1-m8-test',11,'multiple_choice','reading','{"prompt":"Why shouldn''t you send money before seeing the apartment?","options":["Because fake adverts are common","Because it''s illegal","Because prices change"],"answer":0,"passage":{"title":"Renting an apartment abroad","text":"Renting an apartment in another country can be stressful, so here are some tips. First, never send money before you''ve seen the apartment, either in person or on a live video call: fake adverts are common. Ask what the rent includes; in some places, bills such as electricity and internet are extra. Read the contract carefully and check how much notice you have to give before leaving. Take photos of everything on the day you move in, so you can prove what condition the apartment was in. Finally, find out if you need a local guarantor, because many landlords ask for one from foreigners."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m8-test-r2','b1-m8-test',12,'multiple_choice','reading','{"prompt":"Why should you take photos when you move in?","options":["To post on social media","To prove the condition of the apartment","To show your family"],"answer":1,"passage":{"title":"Renting an apartment abroad","text":"Renting an apartment in another country can be stressful, so here are some tips. First, never send money before you''ve seen the apartment, either in person or on a live video call: fake adverts are common. Ask what the rent includes; in some places, bills such as electricity and internet are extra. Read the contract carefully and check how much notice you have to give before leaving. Take photos of everything on the day you move in, so you can prove what condition the apartment was in. Finally, find out if you need a local guarantor, because many landlords ask for one from foreigners."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b1-m8-test-r3','b1-m8-test',13,'multiple_choice','reading','{"prompt":"What do many landlords ask foreigners for?","options":["A local guarantor","A year of rent in advance","A job contract"],"answer":0,"passage":{"title":"Renting an apartment abroad","text":"Renting an apartment in another country can be stressful, so here are some tips. First, never send money before you''ve seen the apartment, either in person or on a live video call: fake adverts are common. Ask what the rent includes; in some places, bills such as electricity and internet are extra. Read the contract carefully and check how much notice you have to give before leaving. Take photos of everything on the day you move in, so you can prove what condition the apartment was in. Finally, find out if you need a local guarantor, because many landlords ask for one from foreigners."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
