insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m1-test-r1','b2-m1-test',11,'multiple_choice','reading','{"prompt":"What surprised the writer on arrival?","options":["How expensive Boston was","How fast people spoke","How easy it was to find a job"],"answer":1,"passage":{"title":"Ten years on","text":"When I left Brazil for Boston ten years ago, I had been working in the same bank for six years and was convinced I would stay there forever. By the time I landed, I had already started to doubt that decision. My English, which I had been studying for most of my adult life, suddenly seemed useless: people spoke faster than any recording I had ever heard. For the first few months I worked in a café, and by Christmas I had learned more English from customers than from any course. Looking back, I don''t regret the move, although I sometimes wonder what would have happened if I had stayed. By next year I will have lived abroad for longer than I worked at the bank, which feels strange, but also like proof that I made the right choice."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m1-test-r2','b2-m1-test',12,'multiple_choice','reading','{"prompt":"Where did the writer learn most English at first?","options":["In a language course","From customers at a café","At the bank"],"answer":1,"passage":{"title":"Ten years on","text":"When I left Brazil for Boston ten years ago, I had been working in the same bank for six years and was convinced I would stay there forever. By the time I landed, I had already started to doubt that decision. My English, which I had been studying for most of my adult life, suddenly seemed useless: people spoke faster than any recording I had ever heard. For the first few months I worked in a café, and by Christmas I had learned more English from customers than from any course. Looking back, I don''t regret the move, although I sometimes wonder what would have happened if I had stayed. By next year I will have lived abroad for longer than I worked at the bank, which feels strange, but also like proof that I made the right choice."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m1-test-r3','b2-m1-test',13,'multiple_choice','reading','{"prompt":"What will be true by next year?","options":["They will have returned to Brazil","They will have lived abroad longer than they worked at the bank","They will have stopped working"],"answer":1,"passage":{"title":"Ten years on","text":"When I left Brazil for Boston ten years ago, I had been working in the same bank for six years and was convinced I would stay there forever. By the time I landed, I had already started to doubt that decision. My English, which I had been studying for most of my adult life, suddenly seemed useless: people spoke faster than any recording I had ever heard. For the first few months I worked in a café, and by Christmas I had learned more English from customers than from any course. Looking back, I don''t regret the move, although I sometimes wonder what would have happened if I had stayed. By next year I will have lived abroad for longer than I worked at the bank, which feels strange, but also like proof that I made the right choice."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m2-test-r1','b2-m2-test',11,'multiple_choice','reading','{"prompt":"What was Paula''s grandmother''s advice?","options":["Save money","Do something you love","Become an engineer"],"answer":1,"passage":{"title":"If only I''d listened","text":"\"If only I''d listened to my grandmother,\" says Paula, a 34-year-old engineer who now runs a small bakery. \"She always told me that if I didn''t do something I loved, I would end up miserable, however much I earned.\" For years Paula ignored the advice. She had a well-paid job, a company car and almost no free time. \"I wish I had realized sooner that the money wasn''t making me happy,\" she admits. The turning point came during a long illness, when she started baking bread at home to pass the time. Friends began ordering loaves, then local cafés. Had she not been forced to stop working, she believes she would never have taken the risk. \"I''d rather earn less and wake up excited,\" she says. \"Although I do wish the bakery started a bit later than four a.m.!\""}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m2-test-r2','b2-m2-test',12,'multiple_choice','reading','{"prompt":"What led Paula to start baking?","options":["She lost her job","A long illness","Her grandmother''s recipes"],"answer":1,"passage":{"title":"If only I''d listened","text":"\"If only I''d listened to my grandmother,\" says Paula, a 34-year-old engineer who now runs a small bakery. \"She always told me that if I didn''t do something I loved, I would end up miserable, however much I earned.\" For years Paula ignored the advice. She had a well-paid job, a company car and almost no free time. \"I wish I had realized sooner that the money wasn''t making me happy,\" she admits. The turning point came during a long illness, when she started baking bread at home to pass the time. Friends began ordering loaves, then local cafés. Had she not been forced to stop working, she believes she would never have taken the risk. \"I''d rather earn less and wake up excited,\" she says. \"Although I do wish the bakery started a bit later than four a.m.!\""}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
