insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m3-test-r1','b2-m3-test',11,'multiple_choice','reading','{"prompt":"What happened to shops in Oslo and Pontevedra?","options":["Many closed","They became busier","They moved to the suburbs"],"answer":1,"passage":{"title":"Should we ban cars from city centers?","text":"Few urban policies divide opinion as sharply as banning cars from city centers. Supporters point to cities such as Oslo and Pontevedra, where pedestrianised streets have led to cleaner air, fewer accidents and, perhaps surprisingly, busier shops. Their argument is simple: streets designed for people attract people. Opponents, however, warn that bans can hit those who have no realistic alternative, such as elderly residents, people with disabilities or workers whose shifts start before public transport runs. Some shopkeepers also fear losing customers who drive in from the suburbs. On balance, the evidence suggests that bans work best when they are introduced gradually and accompanied by better buses, safe cycle lanes and exceptions for those who genuinely need a car. Imposed overnight, they are more likely to provoke a backlash than to change habits."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m3-test-r2','b2-m3-test',12,'multiple_choice','reading','{"prompt":"Who might be hurt by a ban, according to opponents?","options":["Tourists","People without a realistic alternative to the car","Cyclists"],"answer":1,"passage":{"title":"Should we ban cars from city centers?","text":"Few urban policies divide opinion as sharply as banning cars from city centers. Supporters point to cities such as Oslo and Pontevedra, where pedestrianised streets have led to cleaner air, fewer accidents and, perhaps surprisingly, busier shops. Their argument is simple: streets designed for people attract people. Opponents, however, warn that bans can hit those who have no realistic alternative, such as elderly residents, people with disabilities or workers whose shifts start before public transport runs. Some shopkeepers also fear losing customers who drive in from the suburbs. On balance, the evidence suggests that bans work best when they are introduced gradually and accompanied by better buses, safe cycle lanes and exceptions for those who genuinely need a car. Imposed overnight, they are more likely to provoke a backlash than to change habits."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m3-test-r3','b2-m3-test',13,'multiple_choice','reading','{"prompt":"What is the writer''s conclusion?","options":["Bans should be introduced overnight","Bans work best gradually and with alternatives","Bans never work"],"answer":1,"passage":{"title":"Should we ban cars from city centers?","text":"Few urban policies divide opinion as sharply as banning cars from city centers. Supporters point to cities such as Oslo and Pontevedra, where pedestrianised streets have led to cleaner air, fewer accidents and, perhaps surprisingly, busier shops. Their argument is simple: streets designed for people attract people. Opponents, however, warn that bans can hit those who have no realistic alternative, such as elderly residents, people with disabilities or workers whose shifts start before public transport runs. Some shopkeepers also fear losing customers who drive in from the suburbs. On balance, the evidence suggests that bans work best when they are introduced gradually and accompanied by better buses, safe cycle lanes and exceptions for those who genuinely need a car. Imposed overnight, they are more likely to provoke a backlash than to change habits."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m4-test-r1','b2-m4-test',11,'multiple_choice','reading','{"prompt":"How many units were affected in total?","options":["20","35","55"],"answer":2,"passage":{"title":"A formal complaint","text":"Dear Mr. Hughes,\nI am writing to express my concern regarding the shipment we received on 3 March (order 4471). Of the 200 units ordered, 35 arrived damaged, and a further 20 were missing altogether. As a result, we were unable to fulfill two of our own client orders on time, which has caused us considerable inconvenience.\nWhile we appreciate that delays can occur, this is the second incident of this kind in three months. I would therefore be grateful if you could arrange a replacement of the damaged and missing items by the end of next week, and confirm what steps will be taken to prevent a recurrence.\nShould the situation not be resolved, we may need to reconsider our agreement. I look forward to your prompt reply.\nYours sincerely,\nAna Ribeiro\nPurchasing Manager"}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m4-test-r2','b2-m4-test',12,'multiple_choice','reading','{"prompt":"Why is Ana particularly concerned?","options":["It''s the second similar incident in three months","The price went up","The order was canceled"],"answer":0,"passage":{"title":"A formal complaint","text":"Dear Mr. Hughes,\nI am writing to express my concern regarding the shipment we received on 3 March (order 4471). Of the 200 units ordered, 35 arrived damaged, and a further 20 were missing altogether. As a result, we were unable to fulfill two of our own client orders on time, which has caused us considerable inconvenience.\nWhile we appreciate that delays can occur, this is the second incident of this kind in three months. I would therefore be grateful if you could arrange a replacement of the damaged and missing items by the end of next week, and confirm what steps will be taken to prevent a recurrence.\nShould the situation not be resolved, we may need to reconsider our agreement. I look forward to your prompt reply.\nYours sincerely,\nAna Ribeiro\nPurchasing Manager"}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
