insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m5-test-r1','b2-m5-test',11,'multiple_choice','reading','{"prompt":"What did ''nice'' originally mean?","options":["Pleasant","Foolish or ignorant","Beautiful"],"answer":1,"passage":{"title":"Words that changed meaning","text":"Language never stands still, and some everyday English words have traveled a surprisingly long way from their original meanings. ''Nice'', for instance, once meant ''foolish'' or ''ignorant''; it only came to mean ''pleasant'' in the eighteenth century. ''Awful'' used to mean ''full of awe'', that is, deeply impressive, before it drifted towards ''terrible''. More recently, ''literally'' has been widely used to mean its exact opposite, as in ''I literally died laughing'', which annoys many careful speakers but is now recorded in major dictionaries. Linguists generally avoid calling these changes mistakes. Instead, they see them as evidence that meaning is shaped by use: if enough people use a word in a new way for long enough, the new sense becomes part of the language, whether or not we approve."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m5-test-r2','b2-m5-test',12,'multiple_choice','reading','{"prompt":"Why do some speakers dislike the modern use of ''literally''?","options":["It''s too formal","It is used to mean the opposite of its exact meaning","It''s an American word"],"answer":1,"passage":{"title":"Words that changed meaning","text":"Language never stands still, and some everyday English words have traveled a surprisingly long way from their original meanings. ''Nice'', for instance, once meant ''foolish'' or ''ignorant''; it only came to mean ''pleasant'' in the eighteenth century. ''Awful'' used to mean ''full of awe'', that is, deeply impressive, before it drifted towards ''terrible''. More recently, ''literally'' has been widely used to mean its exact opposite, as in ''I literally died laughing'', which annoys many careful speakers but is now recorded in major dictionaries. Linguists generally avoid calling these changes mistakes. Instead, they see them as evidence that meaning is shaped by use: if enough people use a word in a new way for long enough, the new sense becomes part of the language, whether or not we approve."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m5-test-r3','b2-m5-test',13,'multiple_choice','reading','{"prompt":"What is the linguists'' view?","options":["These changes are mistakes","Meaning is shaped by use","Dictionaries should not record new meanings"],"answer":1,"passage":{"title":"Words that changed meaning","text":"Language never stands still, and some everyday English words have traveled a surprisingly long way from their original meanings. ''Nice'', for instance, once meant ''foolish'' or ''ignorant''; it only came to mean ''pleasant'' in the eighteenth century. ''Awful'' used to mean ''full of awe'', that is, deeply impressive, before it drifted towards ''terrible''. More recently, ''literally'' has been widely used to mean its exact opposite, as in ''I literally died laughing'', which annoys many careful speakers but is now recorded in major dictionaries. Linguists generally avoid calling these changes mistakes. Instead, they see them as evidence that meaning is shaped by use: if enough people use a word in a new way for long enough, the new sense becomes part of the language, whether or not we approve."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
