insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m7-test-r1','b2-m7-test',11,'multiple_choice','reading','{"prompt":"What is usually the main problem in understanding native speakers?","options":["Vocabulary","Connected speech and natural features of conversation","Grammar"],"answer":1,"passage":{"title":"Why native speakers are hard to understand","text":"Many learners who read English comfortably are shocked the first time they try to follow a conversation between native speakers. The problem is rarely vocabulary. In connected speech, words blend together: ''what do you want to do?'' can sound like ''whaddaya wanna do?'', and weak forms such as ''to'', ''for'' and ''of'' almost disappear. Speakers also overlap, change topic halfway through a sentence and use fillers like ''you know'' and ''sort of''. Textbook recordings, by contrast, tend to be slow, clear and perfectly polite. The good news is that the ear can be trained. Listening regularly to authentic material slightly above your level, first without and then with a transcript, helps the brain recognize these patterns. Shadowing, repeating what you hear almost at the same time, is particularly effective, because producing the sounds makes them easier to perceive."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m7-test-r2','b2-m7-test',12,'multiple_choice','reading','{"prompt":"How are textbook recordings described?","options":["Fast and natural","Slow, clear and polite","Full of slang"],"answer":1,"passage":{"title":"Why native speakers are hard to understand","text":"Many learners who read English comfortably are shocked the first time they try to follow a conversation between native speakers. The problem is rarely vocabulary. In connected speech, words blend together: ''what do you want to do?'' can sound like ''whaddaya wanna do?'', and weak forms such as ''to'', ''for'' and ''of'' almost disappear. Speakers also overlap, change topic halfway through a sentence and use fillers like ''you know'' and ''sort of''. Textbook recordings, by contrast, tend to be slow, clear and perfectly polite. The good news is that the ear can be trained. Listening regularly to authentic material slightly above your level, first without and then with a transcript, helps the brain recognize these patterns. Shadowing, repeating what you hear almost at the same time, is particularly effective, because producing the sounds makes them easier to perceive."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m7-test-r3','b2-m7-test',13,'multiple_choice','reading','{"prompt":"Why is shadowing effective, according to the text?","options":["It''s fun","Producing the sounds makes them easier to perceive","It improves grammar"],"answer":1,"passage":{"title":"Why native speakers are hard to understand","text":"Many learners who read English comfortably are shocked the first time they try to follow a conversation between native speakers. The problem is rarely vocabulary. In connected speech, words blend together: ''what do you want to do?'' can sound like ''whaddaya wanna do?'', and weak forms such as ''to'', ''for'' and ''of'' almost disappear. Speakers also overlap, change topic halfway through a sentence and use fillers like ''you know'' and ''sort of''. Textbook recordings, by contrast, tend to be slow, clear and perfectly polite. The good news is that the ear can be trained. Listening regularly to authentic material slightly above your level, first without and then with a transcript, helps the brain recognize these patterns. Shadowing, repeating what you hear almost at the same time, is particularly effective, because producing the sounds makes them easier to perceive."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
