insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('b2-m8-test-r3','b2-m8-test',13,'multiple_choice','reading','{"prompt":"Why is rehearsing out loud important?","options":["To memorize every word","To discover weak points in the talk","To use more slides"],"answer":1,"passage":{"title":"What really makes a good presentation","text":"What audiences remember is rarely the data on the slides; it is the story the speaker tells about it. It is clarity, not complexity, that persuades. Never have so many people had access to presentation software, yet rarely have presentations been so forgettable: forty slides of bullet points, read aloud word for word. The best speakers do the opposite. What they do first is decide the one message the audience should leave with, and only then choose the evidence that supports it. Only after that do they think about slides, and when they do, they use few words and plenty of images. Above all, they rehearse. Not until you have said your talk out loud several times will you discover where it drags, where an example is missing, or where you simply don''t know what comes next."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
