insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m2-test-e8','c1-m2-test',8,'listening','listening','{"prompt":"Ouça e escolha.","audio":"The majority of respondents favored a four-day week.","options":["A maioria preferiu semana de quatro dias.","Ninguém quis mudança.","A minoria preferiu quatro dias."],"answer":0}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m3-test-r1','c1-m3-test',11,'multiple_choice','reading','{"prompt":"How do critics usually describe the four-day week?","options":["As a luxury businesses can''t afford","As the future of work","As illegal"],"answer":0,"passage":{"title":"The case for a four-day week","text":"Critics of the four-day working week tend to frame it as a luxury: an appealing idea, perhaps, but one that businesses can ill afford. The evidence from recent trials points in a rather different direction. In pilot schemes involving dozens of companies, productivity was largely maintained, sick days fell and staff turnover dropped, which, given the cost of recruiting and training replacements, is no small saving. Admittedly, the model is not universally applicable. Hospitals, schools and other services that depend on continuous cover cannot simply close on Fridays, and some firms found that a compressed week merely crammed the same stress into fewer days. Yet the question is not whether every organization should adopt it tomorrow, but whether we are prepared to rethink a five-day structure that was designed for factories a century ago. Dismissing the idea out of hand seems, at the very least, premature."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m3-test-r2','c1-m3-test',12,'multiple_choice','reading','{"prompt":"Which result of the trials is presented as a significant saving?","options":["Lower salaries","Reduced staff turnover","Smaller offices"],"answer":1,"passage":{"title":"The case for a four-day week","text":"Critics of the four-day working week tend to frame it as a luxury: an appealing idea, perhaps, but one that businesses can ill afford. The evidence from recent trials points in a rather different direction. In pilot schemes involving dozens of companies, productivity was largely maintained, sick days fell and staff turnover dropped, which, given the cost of recruiting and training replacements, is no small saving. Admittedly, the model is not universally applicable. Hospitals, schools and other services that depend on continuous cover cannot simply close on Fridays, and some firms found that a compressed week merely crammed the same stress into fewer days. Yet the question is not whether every organization should adopt it tomorrow, but whether we are prepared to rethink a five-day structure that was designed for factories a century ago. Dismissing the idea out of hand seems, at the very least, premature."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m3-test-r3','c1-m3-test',13,'multiple_choice','reading','{"prompt":"What is the writer''s position?","options":["Every company should adopt it immediately","Rejecting the idea without consideration is premature","The five-day week is perfect"],"answer":1,"passage":{"title":"The case for a four-day week","text":"Critics of the four-day working week tend to frame it as a luxury: an appealing idea, perhaps, but one that businesses can ill afford. The evidence from recent trials points in a rather different direction. In pilot schemes involving dozens of companies, productivity was largely maintained, sick days fell and staff turnover dropped, which, given the cost of recruiting and training replacements, is no small saving. Admittedly, the model is not universally applicable. Hospitals, schools and other services that depend on continuous cover cannot simply close on Fridays, and some firms found that a compressed week merely crammed the same stress into fewer days. Yet the question is not whether every organization should adopt it tomorrow, but whether we are prepared to rethink a five-day structure that was designed for factories a century ago. Dismissing the idea out of hand seems, at the very least, premature."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
