insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m4-test-r1','c1-m4-test',11,'multiple_choice','reading','{"prompt":"Which word for having little body fat is described as complimentary?","options":["Thin","Slim","Skinny"],"answer":1,"passage":{"title":"Nuance in everyday words","text":"Advanced learners often discover that words they considered synonyms are anything but. ''Thin'', ''slim'' and ''skinny'' all describe someone with little body fat, yet ''slim'' is complimentary, ''thin'' is neutral or slightly worrying, and ''skinny'' can sound critical or, in fashion, simply descriptive. Similarly, ''stubborn'' and ''determined'' may describe exactly the same behavior; the choice reveals whether the speaker approves of it. Collocation matters too: we say ''heavy rain'' but ''strong wind'', ''make a decision'' but ''do your homework'', and a ''tall building'' but a ''high mountain''. None of these combinations is logical, which is precisely why they mark a speaker as fluent. Rather than memorizing lists, the most efficient strategy is to notice words in context and record the phrases they typically appear in, not just their dictionary definitions."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m4-test-r2','c1-m4-test',12,'multiple_choice','reading','{"prompt":"What does choosing ''stubborn'' instead of ''determined'' reveal?","options":["The speaker''s approval or disapproval","The person''s age","Formality"],"answer":0,"passage":{"title":"Nuance in everyday words","text":"Advanced learners often discover that words they considered synonyms are anything but. ''Thin'', ''slim'' and ''skinny'' all describe someone with little body fat, yet ''slim'' is complimentary, ''thin'' is neutral or slightly worrying, and ''skinny'' can sound critical or, in fashion, simply descriptive. Similarly, ''stubborn'' and ''determined'' may describe exactly the same behavior; the choice reveals whether the speaker approves of it. Collocation matters too: we say ''heavy rain'' but ''strong wind'', ''make a decision'' but ''do your homework'', and a ''tall building'' but a ''high mountain''. None of these combinations is logical, which is precisely why they mark a speaker as fluent. Rather than memorizing lists, the most efficient strategy is to notice words in context and record the phrases they typically appear in, not just their dictionary definitions."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m4-test-r3','c1-m4-test',13,'multiple_choice','reading','{"prompt":"What strategy does the writer recommend?","options":["Memorizing synonym lists","Noticing words in context and recording typical phrases","Using a thesaurus"],"answer":1,"passage":{"title":"Nuance in everyday words","text":"Advanced learners often discover that words they considered synonyms are anything but. ''Thin'', ''slim'' and ''skinny'' all describe someone with little body fat, yet ''slim'' is complimentary, ''thin'' is neutral or slightly worrying, and ''skinny'' can sound critical or, in fashion, simply descriptive. Similarly, ''stubborn'' and ''determined'' may describe exactly the same behavior; the choice reveals whether the speaker approves of it. Collocation matters too: we say ''heavy rain'' but ''strong wind'', ''make a decision'' but ''do your homework'', and a ''tall building'' but a ''high mountain''. None of these combinations is logical, which is precisely why they mark a speaker as fluent. Rather than memorizing lists, the most efficient strategy is to notice words in context and record the phrases they typically appear in, not just their dictionary definitions."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m5-test-r1','c1-m5-test',11,'multiple_choice','reading','{"prompt":"Why is the team being restructured?","options":["To cut jobs","To reduce resolution times and build expertise","To move offices"],"answer":1,"passage":{"title":"Memo: restructuring the support team","text":"To: All Customer Support Staff\nFrom: Operations Director\nRe: Changes to team structure\nFollowing a review of last year''s performance, we will be restructuring the support function with effect from 1 June. Rather than handling all inquiries in a single line, the team will be divided into two specialist groups: one dedicated to technical issues and the other to billing and accounts. The aim is to reduce average resolution times, which rose by 18% last year, and to give staff the opportunity to develop deeper expertise.\nWe recognize that change of this kind can be unsettling. Let me stress that no roles will be lost as a result of the restructuring. Team leaders will meet each member of staff individually over the coming two weeks to discuss preferences, and every effort will be made to accommodate them. Training for both groups will begin in mid-May."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m5-test-r2','c1-m5-test',12,'multiple_choice','reading','{"prompt":"What reassurance does the memo give?","options":["Salaries will rise","No roles will be lost","Training is optional"],"answer":1,"passage":{"title":"Memo: restructuring the support team","text":"To: All Customer Support Staff\nFrom: Operations Director\nRe: Changes to team structure\nFollowing a review of last year''s performance, we will be restructuring the support function with effect from 1 June. Rather than handling all inquiries in a single line, the team will be divided into two specialist groups: one dedicated to technical issues and the other to billing and accounts. The aim is to reduce average resolution times, which rose by 18% last year, and to give staff the opportunity to develop deeper expertise.\nWe recognize that change of this kind can be unsettling. Let me stress that no roles will be lost as a result of the restructuring. Team leaders will meet each member of staff individually over the coming two weeks to discuss preferences, and every effort will be made to accommodate them. Training for both groups will begin in mid-May."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m5-test-r3','c1-m5-test',13,'multiple_choice','reading','{"prompt":"What will happen over the next two weeks?","options":["Team leaders will meet each staff member individually","Training will start","The new structure will begin"],"answer":0,"passage":{"title":"Memo: restructuring the support team","text":"To: All Customer Support Staff\nFrom: Operations Director\nRe: Changes to team structure\nFollowing a review of last year''s performance, we will be restructuring the support function with effect from 1 June. Rather than handling all inquiries in a single line, the team will be divided into two specialist groups: one dedicated to technical issues and the other to billing and accounts. The aim is to reduce average resolution times, which rose by 18% last year, and to give staff the opportunity to develop deeper expertise.\nWe recognize that change of this kind can be unsettling. Let me stress that no roles will be lost as a result of the restructuring. Team leaders will meet each member of staff individually over the coming two weeks to discuss preferences, and every effort will be made to accommodate them. Training for both groups will begin in mid-May."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m6-test-r1','c1-m6-test',11,'multiple_choice','reading','{"prompt":"What does the reader realize halfway through?","options":["The narrator may not be reliable","The storm never happened","The book is a comedy"],"answer":0,"passage":{"title":"Review: a novel that refuses easy answers","text":"There is a moment, roughly halfway through ''The Quiet Harbour'', when the reader realizes that the narrator cannot be entirely trusted. It is handled so deftly that one is tempted to go back to the beginning and reread every conversation in a new light. This is a novel that resists easy answers: the central mystery, what really happened on the night of the storm, is never fully resolved, and readers who demand neat endings may find this frustrating. Others will see it as the book''s greatest strength. The prose is restrained, occasionally to a fault; there are passages in the second half where the tension slackens and the author''s fondness for description slows things to a crawl. Even so, it is a remarkably assured debut, and one whose characters linger in the mind long after the final page."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m6-test-r2','c1-m6-test',12,'multiple_choice','reading','{"prompt":"Which readers might be frustrated?","options":["Those who like long descriptions","Those who want neat, resolved endings","Those who dislike mysteries"],"answer":1,"passage":{"title":"Review: a novel that refuses easy answers","text":"There is a moment, roughly halfway through ''The Quiet Harbour'', when the reader realizes that the narrator cannot be entirely trusted. It is handled so deftly that one is tempted to go back to the beginning and reread every conversation in a new light. This is a novel that resists easy answers: the central mystery, what really happened on the night of the storm, is never fully resolved, and readers who demand neat endings may find this frustrating. Others will see it as the book''s greatest strength. The prose is restrained, occasionally to a fault; there are passages in the second half where the tension slackens and the author''s fondness for description slows things to a crawl. Even so, it is a remarkably assured debut, and one whose characters linger in the mind long after the final page."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m6-test-r3','c1-m6-test',13,'multiple_choice','reading','{"prompt":"What does ''restrained, occasionally to a fault'' imply?","options":["The writing is always perfect","The style is controlled but sometimes too much so","The book is too short"],"answer":1,"passage":{"title":"Review: a novel that refuses easy answers","text":"There is a moment, roughly halfway through ''The Quiet Harbour'', when the reader realizes that the narrator cannot be entirely trusted. It is handled so deftly that one is tempted to go back to the beginning and reread every conversation in a new light. This is a novel that resists easy answers: the central mystery, what really happened on the night of the storm, is never fully resolved, and readers who demand neat endings may find this frustrating. Others will see it as the book''s greatest strength. The prose is restrained, occasionally to a fault; there are passages in the second half where the tension slackens and the author''s fondness for description slows things to a crawl. Even so, it is a remarkably assured debut, and one whose characters linger in the mind long after the final page."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m7-test-r3','c1-m7-test',13,'multiple_choice','reading','{"prompt":"What solution does the writer favor?","options":["Banning social media","Rebuilding everyday spaces where people can meet","Working from home"],"answer":1,"passage":{"title":"The loneliness paradox","text":"We have never been more connected, yet surveys across several countries suggest that loneliness is on the rise, particularly among young adults, a group long assumed to be the most socially active. The obvious culprit is social media, and there is some evidence that passive scrolling, comparing one''s own life with curated highlights of others'', leaves people feeling worse. But the explanation is probably more complex. Work has become more mobile, people move cities more often, and the informal places where communities once formed, clubs, local pubs, places of worship, have declined. Loneliness, researchers stress, is not the same as being alone: it is the gap between the relationships we have and those we want. Tackling it may therefore depend less on limiting screen time than on rebuilding everyday spaces where people can meet without needing a reason."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c1-m8-test-r2','c1-m8-test',12,'multiple_choice','reading','{"prompt":"What does the writer recommend?","options":["Imitating native speakers completely","Adopting expressions that fit your own personality","Avoiding humor"],"answer":1,"passage":{"title":"Finding your voice in a second language","text":"Many proficient speakers report feeling like a slightly different person in their second language: more formal, perhaps, or less funny, or oddly more direct. This is not merely imagination. Humour, irony and small talk rely heavily on shared cultural references and on the confidence to play with language, and both take time to develop. For a while, the safest strategy is to speak correctly rather than personally, which can make us sound flatter than we are. The way forward is not to imitate native speakers wholesale but to notice the expressions that fit our own personality and gradually make them ours. Someone who is naturally understated might adopt ''not bad at all'' rather than ''amazing''; someone who loves wordplay might start collecting idioms to twist. Fluency, in the end, is less about sounding native than about sounding like yourself."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
