insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m1-test-r1','c2-m1-test',11,'multiple_choice','reading','{"prompt":"How does science advance, according to the writer?","options":["By confirming existing beliefs","By discovering that theories don''t survive the evidence","By avoiding mistakes"],"answer":1,"passage":{"title":"On the virtues of being wrong","text":"Seldom do we celebrate being wrong, and yet it is arguably the only route by which anyone has ever learned anything. Science advances not by confirming what it already believes but by discovering, often to the considerable embarrassment of those concerned, that cherished theories do not survive contact with the evidence. Were individuals to adopt the same attitude, much needless conflict might be avoided. The difficulty is that being wrong rarely feels like anything at all until the moment we realize it; up to that point, it feels exactly like being right. Hence the peculiar confidence with which people defend positions they would, given more information, abandon without a second thought. Cultivating intellectual humility, then, is not a matter of doubting everything, which would be paralyzing, but of holding one''s views with a grip firm enough to act on and loose enough to revise."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m1-test-r2','c2-m1-test',12,'multiple_choice','reading','{"prompt":"Why do people defend wrong positions so confidently?","options":["Being wrong feels exactly like being right until we realize it","They enjoy arguing","They lack education"],"answer":0,"passage":{"title":"On the virtues of being wrong","text":"Seldom do we celebrate being wrong, and yet it is arguably the only route by which anyone has ever learned anything. Science advances not by confirming what it already believes but by discovering, often to the considerable embarrassment of those concerned, that cherished theories do not survive contact with the evidence. Were individuals to adopt the same attitude, much needless conflict might be avoided. The difficulty is that being wrong rarely feels like anything at all until the moment we realize it; up to that point, it feels exactly like being right. Hence the peculiar confidence with which people defend positions they would, given more information, abandon without a second thought. Cultivating intellectual humility, then, is not a matter of doubting everything, which would be paralyzing, but of holding one''s views with a grip firm enough to act on and loose enough to revise."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m1-test-r3','c2-m1-test',13,'multiple_choice','reading','{"prompt":"What does intellectual humility mean here?","options":["Doubting everything","Holding views firmly enough to act but loosely enough to revise","Never expressing opinions"],"answer":1,"passage":{"title":"On the virtues of being wrong","text":"Seldom do we celebrate being wrong, and yet it is arguably the only route by which anyone has ever learned anything. Science advances not by confirming what it already believes but by discovering, often to the considerable embarrassment of those concerned, that cherished theories do not survive contact with the evidence. Were individuals to adopt the same attitude, much needless conflict might be avoided. The difficulty is that being wrong rarely feels like anything at all until the moment we realize it; up to that point, it feels exactly like being right. Hence the peculiar confidence with which people defend positions they would, given more information, abandon without a second thought. Cultivating intellectual humility, then, is not a matter of doubting everything, which would be paralyzing, but of holding one''s views with a grip firm enough to act on and loose enough to revise."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
