insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m3-test-r1','c2-m3-test',11,'multiple_choice','reading','{"prompt":"What is humorous about the thanks to the judges?","options":["The speaker never liked them","The speaker admires them more now that they''ve won","The judges were absent"],"answer":1,"passage":{"title":"Speech: accepting an award","text":"I''m conscious that the last thing anyone wants at this point in the evening is a long speech, so I''ll confine myself to three thank-yous and one confession. Thank you to the judges, whose judgment I have always admired and, as of tonight, admire rather more. Thank you to my team, who did most of the work while I did most of the worrying. And thank you to my family, who have heard more about supply chains over dinner than any family should have to. Now, the confession. When we started this project, I was fairly sure it would fail. That we''re here at all is less a tribute to my vision than to the stubbornness of people who refused to listen to me. If there''s a lesson in that, it''s perhaps this: surround yourself with people who are prepared to tell you you''re wrong, and then, occasionally, let them win."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m3-test-r2','c2-m3-test',12,'multiple_choice','reading','{"prompt":"What is the speaker''s confession?","options":["They didn''t do the project","They expected the project to fail","They wrote the speech that afternoon"],"answer":1,"passage":{"title":"Speech: accepting an award","text":"I''m conscious that the last thing anyone wants at this point in the evening is a long speech, so I''ll confine myself to three thank-yous and one confession. Thank you to the judges, whose judgment I have always admired and, as of tonight, admire rather more. Thank you to my team, who did most of the work while I did most of the worrying. And thank you to my family, who have heard more about supply chains over dinner than any family should have to. Now, the confession. When we started this project, I was fairly sure it would fail. That we''re here at all is less a tribute to my vision than to the stubbornness of people who refused to listen to me. If there''s a lesson in that, it''s perhaps this: surround yourself with people who are prepared to tell you you''re wrong, and then, occasionally, let them win."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
