insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m5-test-r1','c2-m5-test',11,'multiple_choice','reading','{"prompt":"What is notably absent from the reference?","options":["Dates of employment","Any praise of the quality of his work","The company name"],"answer":1,"passage":{"title":"Reading between the lines of a reference","text":"To whom it may concern: I am pleased to confirm that Mr. Daniel Hart was employed by our firm from 2019 to 2024. During this period he was invariably punctual, and his desk was always impeccably tidy. Mr. Hart has a keen interest in a wide range of subjects, many of them unrelated to his duties, which he was always happy to discuss with colleagues at length. He approached every task with considerable enthusiasm, if not always with a clear sense of its purpose. I have no doubt that, in the right role, he would be an asset to any organization. Should you require further information, I would be happy to provide it by telephone."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m5-test-r2','c2-m5-test',12,'multiple_choice','reading','{"prompt":"What does ''happy to discuss with colleagues at length'' most likely imply?","options":["He was a good communicator","He distracted colleagues with long conversations","He trained new staff"],"answer":1,"passage":{"title":"Reading between the lines of a reference","text":"To whom it may concern: I am pleased to confirm that Mr. Daniel Hart was employed by our firm from 2019 to 2024. During this period he was invariably punctual, and his desk was always impeccably tidy. Mr. Hart has a keen interest in a wide range of subjects, many of them unrelated to his duties, which he was always happy to discuss with colleagues at length. He approached every task with considerable enthusiasm, if not always with a clear sense of its purpose. I have no doubt that, in the right role, he would be an asset to any organization. Should you require further information, I would be happy to provide it by telephone."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m5-test-r3','c2-m5-test',13,'multiple_choice','reading','{"prompt":"Why might the writer prefer to give further information by telephone?","options":["It''s faster","They may want to say things they won''t put in writing","They don''t use email"],"answer":1,"passage":{"title":"Reading between the lines of a reference","text":"To whom it may concern: I am pleased to confirm that Mr. Daniel Hart was employed by our firm from 2019 to 2024. During this period he was invariably punctual, and his desk was always impeccably tidy. Mr. Hart has a keen interest in a wide range of subjects, many of them unrelated to his duties, which he was always happy to discuss with colleagues at length. He approached every task with considerable enthusiasm, if not always with a clear sense of its purpose. I have no doubt that, in the right role, he would be an asset to any organization. Should you require further information, I would be happy to provide it by telephone."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m7-test-r1','c2-m7-test',11,'multiple_choice','reading','{"prompt":"What characterises the ''comfortable plateau''?","options":["Constant difficulty communicating","Good communication but no real improvement for years","Rapid progress"],"answer":1,"passage":{"title":"The illusion of fluency","text":"There is a stage in language learning that might be called the comfortable plateau. You can follow movies, hold your own in meetings and rarely need a dictionary; yet, if you are honest, your English has not noticeably improved in years. The cause is seldom laziness. Rather, once communication succeeds, the pressure to refine it disappears: people understand you, so the slightly unnatural collocations and the handful of habitual errors go uncorrected. Escaping the plateau requires deliberately reintroducing difficulty. Recording yourself and comparing the transcript with how a highly proficient speaker would express the same ideas is humbling but revealing. So is writing in genres you never use, such as formal complaints, persuasive essays or speeches. Above all, it means asking for correction from people who will give it, since politeness, at this level, is the enemy of progress."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m7-test-r2','c2-m7-test',12,'multiple_choice','reading','{"prompt":"Why do errors go uncorrected at this stage?","options":["Communication succeeds, so there is no pressure to refine","Learners are lazy","Teachers are unavailable"],"answer":0,"passage":{"title":"The illusion of fluency","text":"There is a stage in language learning that might be called the comfortable plateau. You can follow movies, hold your own in meetings and rarely need a dictionary; yet, if you are honest, your English has not noticeably improved in years. The cause is seldom laziness. Rather, once communication succeeds, the pressure to refine it disappears: people understand you, so the slightly unnatural collocations and the handful of habitual errors go uncorrected. Escaping the plateau requires deliberately reintroducing difficulty. Recording yourself and comparing the transcript with how a highly proficient speaker would express the same ideas is humbling but revealing. So is writing in genres you never use, such as formal complaints, persuasive essays or speeches. Above all, it means asking for correction from people who will give it, since politeness, at this level, is the enemy of progress."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
insert into public.exercises (id,lesson_id,sort,type,skill,payload) values ('c2-m7-test-r3','c2-m7-test',13,'multiple_choice','reading','{"prompt":"Why is politeness called ''the enemy of progress''?","options":["People avoid correcting you","Polite language is less accurate","It wastes time"],"answer":0,"passage":{"title":"The illusion of fluency","text":"There is a stage in language learning that might be called the comfortable plateau. You can follow movies, hold your own in meetings and rarely need a dictionary; yet, if you are honest, your English has not noticeably improved in years. The cause is seldom laziness. Rather, once communication succeeds, the pressure to refine it disappears: people understand you, so the slightly unnatural collocations and the handful of habitual errors go uncorrected. Escaping the plateau requires deliberately reintroducing difficulty. Recording yourself and comparing the transcript with how a highly proficient speaker would express the same ideas is humbling but revealing. So is writing in genres you never use, such as formal complaints, persuasive essays or speeches. Above all, it means asking for correction from people who will give it, since politeness, at this level, is the enemy of progress."}}'::jsonb) on conflict (id) do update set sort=excluded.sort, type=excluded.type, skill=excluded.skill, payload=excluded.payload;
